+/**
+ * Returns the native messageManager group associated with the given WebExtension
+ * linkHandler.
+ *
+ * @param {string} linkHandler
+ * @returns {string}
+ */
+export function getMessageManagerGroup(linkHandler) {
+  switch (linkHandler) {
+    case "relaxed":
+      return "browsers";
+    case "strict":
+      return "single-page";
+    case "balanced":
+    default:
+      return "single-site";
+  }
+}
